import fs from "node:fs";
import { execFileSync } from "node:child_process";

// Refresh the browser engine bridge from the pinned GeoLibre source and tool
// inventories. Keep this deterministic: no generated file depends on the
// checkout's current branch or a network fetch.
const commit = "ffe2665a3b9f32d99fe9bace47fc6fdac4e4e8ae";
const base = "src/lib/browser";
fs.mkdirSync(base, { recursive: true });

for (const name of ["wasm-tool-runner.ts", "wasm-tool.worker.ts"]) {
  let source = execFileSync("git", ["-C", "reference/gis/GeoLibre", "show", `${commit}:packages/processing/src/${name}`], { encoding: "utf8" });
  if (name === "wasm-tool.worker.ts") {
    source = source
      .replace('import { runTool } from "geolibre-wasm/tools";', 'import { runTool } from "geolibre-wasm/tools";\nimport initLibrary, { vector_info, vector_to_geojson } from "geolibre-wasm";')
      .replace('    const result = await runTool(tool, { args, input });', `    // TIPHYS addition: inspect the actual source CRS before accepting an import.
    let result: ToolResult;
    if (tool === "__tiphys_info") {
      await initLibrary();
      const format = args.find(a => a.startsWith("--format="))?.slice(9) ?? "geojson";
      result = { exitCode: 0, stdout: [vector_info(Object.values(input)[0], format)], files: {} };
    } else if (tool === "__tiphys_geojson") {
      await initLibrary();
      const format = args.find(a => a.startsWith("--format="))?.slice(9) ?? "geojson";
      result = { exitCode: 0, stdout: [vector_to_geojson(Object.values(input)[0], format)], files: {} };
    } else result = await runTool(tool, { args, input });`);
    for (const hook of ["__tiphys_info", "__tiphys_geojson"]) if (!source.includes(`tool === "${hook}"`)) throw new Error(`Failed to add TIPHYS worker hook ${hook}; upstream worker source changed.`);
  }
  fs.writeFileSync(`${base}/${name}`, `// Reused from opengeos/GeoLibre @ ${commit}; MIT, Copyright 2026 Qiusheng Wu.\n// Original notice: docs/licenses/GeoLibre-MIT.txt.\n${source}`);
}
fs.mkdirSync("docs/licenses", { recursive: true });
fs.writeFileSync("docs/licenses/GeoLibre-MIT.txt", execFileSync("git", ["-C", "reference/gis/GeoLibre", "show", `${commit}:LICENSE`]));

const { tools } = JSON.parse(fs.readFileSync(".tooling/source-catalog.json", "utf8"));
for (const tool of tools) tool.description = (tool.description ?? "").replaceAll("geopandas", "GeoLibre WASM").replaceAll("GeoPandas", "GeoLibre WASM");
// Workspace-management tools added after source-catalog.json was captured; the
// browser bridge implements the same contracts as the Python engine's MCP tools.
for (const extra of [
  { name: "rename_layer", description: "重命名图层的显示名称，不改动分析数据。", category: "数据管理",
    parameters: { type: "object", properties: { layer: { type: "string", "x-layer": true, description: "图层 ID 或名称" }, name: { type: "string", description: "新的显示名称（唯一且非空）" } }, required: ["layer", "name"], additionalProperties: false } },
  { name: "reorder_layers", description: "设置工作区图层顺序，即地图绘制顺序（越靠后越在上层）。", category: "数据管理",
    parameters: { type: "object", properties: { layer_ids: { type: "array", items: { type: "string" }, description: "全部现有图层 ID，每个一次，按目标顺序" } }, required: ["layer_ids"], additionalProperties: false } },
  { name: "field_statistics", description: "统计图层某个属性字段：数值字段给出最小/最大/均值/中位数/标准差，其他字段给出最常见值；空值单独计数。", category: "查询与选择",
    parameters: { type: "object", properties: { layer: { type: "string", "x-layer": true, description: "图层 ID 或名称" }, field: { type: "string", description: "字段名" } }, required: ["layer", "field"], additionalProperties: false } },
]) if (!tools.some(tool => tool.name === extra.name)) tools.push(extra);
const exporter = tools.find(tool => tool.name === "export_features");
const formats = exporter?.parameters?.properties?.fmt;
if (formats?.enum) {
  formats.enum = [...new Set([...formats.enum, "fgb", "csv"])];
  exporter.description = String(exporter.description).replace(/csv\.?(?=\n|$)/, "")
    + " CSV output is generated by the browser bridge with a WKT geometry column in the layer's source CRS."
    + " GeoJSON exports can carry top-level metadata (for example dropped_count); gpkg/fgb/csv report it as not supported.";
  exporter.parameters.properties.metadata ??= {
    type: "object", title: "Metadata", additionalProperties: true,
    description: "Optional top-level metadata for GeoJSON exports (for example dropped_count).",
  };
}
fs.writeFileSync(`${base}/catalog.json`, JSON.stringify(tools, null, 2));

const manifests = JSON.parse(fs.readFileSync(".tooling/wasm-manifests.json", "utf8"));
// The layer bridge accepts vector, raster and table inputs, publishes the same
// kinds as layers and returns file/text/json outputs as attachments. Tools are
// exposed when every input is one of those kinds and every non-io parameter is
// a single-value scalar/bool/string/enum — everything else (LiDAR, multi-value
// and free-form parameters) stays hidden until the bridge grows that support.
const MAP_IO = new Set(["vector", "raster", "table"]);
const ATTACH_OUT = new Set(["file", "text", "json"]);
const native = manifests.filter(tool =>
  String(tool.license_tier ?? "open").toLowerCase() === "open" &&
  tool.params.some(param => param.io_role === "output" && (MAP_IO.has(param.data_kind) || ATTACH_OUT.has(param.data_kind))) &&
  tool.params.every(param => {
    if (param.io_role === "input") return MAP_IO.has(param.data_kind) && param.schema?.cardinality !== "multiple";
    if (param.io_role === "output") return MAP_IO.has(param.data_kind) || ATTACH_OUT.has(param.data_kind);
    return ["string", "bool", "scalar", "enum"].includes(param.schema?.kind) && param.schema?.cardinality !== "multiple";
  }));
fs.writeFileSync(`${base}/wasm-catalog.json`, JSON.stringify(native));

// Merge the reviewed Chinese tool dictionary (translated from the manifests)
// into src/lib/i18n so the toolbox and Agent-facing catalog can localize names
// and descriptions without touching upstream text.
fs.mkdirSync("src/lib/i18n", { recursive: true });
const zh = {};
let zhParts = 0;
for (const file of fs.readdirSync(".tooling/zh-slices")) {
  if (!/^zh-part\d+\.json$/.test(file)) continue;
  Object.assign(zh, JSON.parse(fs.readFileSync(`.tooling/zh-slices/${file}`, "utf8")));
  zhParts++;
}
fs.writeFileSync("src/lib/i18n/tool-zh.json", JSON.stringify(zh, null, 1));

fs.mkdirSync("public/samples", { recursive: true });
for (const file of fs.readdirSync("samples")) if (file.endsWith(".geojson")) fs.copyFileSync(`samples/${file}`, `public/samples/${file}`);
console.log(JSON.stringify({ commit, common: tools.length, nativeTools: native.length, zhParts, zhEntries: Object.keys(zh).length, unionLayers: tools.some(tool => tool.name === "union_layers"), calculateGeometry: tools.some(tool => tool.name === "calculate_geometry") }));
